import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { sleepyPaths } from '../paths.js';

export type QueueItemType = 'code' | 'research' | 'content' | 'plans' | 'findings';

export interface BranchArtifact {
  kind: 'branch';
  name: string;
}

export interface FileArtifact {
  kind: 'file';
  path: string;
}

export type QueueArtifact = BranchArtifact | FileArtifact;

export interface QueueItem {
  number: number;
  type: QueueItemType;
  summary: string;
  artifact: QueueArtifact;
  size: string;
  addedAt: string;
  approved: boolean;
}

const BRANCH_RE = /^branch\s+`([^`]+)`$/;
const FILE_RE = /^`([^`]+)`$/;

function parseArtifact(raw: string): QueueArtifact | null {
  const trimmed = raw.trim();
  const branchMatch = BRANCH_RE.exec(trimmed);
  if (branchMatch) return { kind: 'branch', name: branchMatch[1]! };
  const fileMatch = FILE_RE.exec(trimmed);
  if (fileMatch) return { kind: 'file', path: fileMatch[1]! };
  return null;
}

function parseType(raw: string): QueueItemType | null {
  const t = raw.trim();
  if (
    t === 'code' ||
    t === 'research' ||
    t === 'content' ||
    t === 'plans' ||
    t === 'findings'
  ) {
    return t;
  }
  return null;
}

function parseRow(line: string): QueueItem | null {
  const cells = line
    .split('|')
    .map((c) => c.trim())
    .filter((c, idx, arr) => !(idx === 0 && c === '') && !(idx === arr.length - 1 && c === ''));
  if (cells.length !== 7) return null;

  const [numStr, typeStr, summary, artifactStr, size, addedAt, statusStr] = cells as [
    string, string, string, string, string, string, string,
  ];
  const number = Number(numStr);
  if (!Number.isInteger(number) || number <= 0) return null;

  const type = parseType(typeStr);
  if (!type) return null;

  const artifact = parseArtifact(artifactStr);
  if (!artifact) return null;

  const approved = /\[[xX]\]/.test(statusStr);

  return {
    number,
    type,
    summary: summary.trim(),
    artifact,
    size: size.trim(),
    addedAt: addedAt.trim(),
    approved,
  };
}

export async function readQueue(projectRoot: string): Promise<QueueItem[]> {
  const paths = sleepyPaths(projectRoot);
  let raw: string;
  try {
    raw = await readFile(paths.queueMd, 'utf8');
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw err;
  }
  const items: QueueItem[] = [];
  for (const line of raw.split(/\r?\n/)) {
    if (!line.startsWith('|')) continue;
    if (line.includes('---')) continue;
    if (line.includes('| #') && line.includes('| Type')) continue;
    const item = parseRow(line);
    if (item) items.push(item);
  }
  return items;
}

export interface NewQueueItem {
  type: QueueItemType;
  summary: string;
  artifact: QueueArtifact;
  size: string;
  addedAt: string;
}

const HEADER_LINES = [
  '# Review Queue',
  '',
  'Generated by sleepy.',
  '',
  '| # | Type | Summary | Artifact | Size | Added | Status |',
  '|---|------|---------|----------|------|-------|--------|',
];

function renderArtifact(a: QueueArtifact): string {
  return a.kind === 'branch' ? `branch \`${a.name}\`` : `\`${a.path}\``;
}

function renderRow(item: QueueItem): string {
  return `| ${item.number} | ${item.type} | ${item.summary} | ${renderArtifact(
    item.artifact,
  )} | ${item.size} | ${item.addedAt} | ${item.approved ? '[x]' : '[ ]'} |`;
}

export async function appendQueueItem(
  projectRoot: string,
  item: NewQueueItem,
): Promise<QueueItem> {
  const existing = await readQueue(projectRoot);
  const number = existing.length > 0 ? existing[existing.length - 1]!.number + 1 : 1;
  const full: QueueItem = { ...item, number, approved: false };
  existing.push(full);

  const body = [...HEADER_LINES, ...existing.map(renderRow), ''].join('\n');
  const paths = sleepyPaths(projectRoot);
  await mkdir(path.dirname(paths.queueMd), { recursive: true });
  const tmp = `${paths.queueMd}.tmp-${process.pid}-${Date.now()}`;
  await writeFile(tmp, body, 'utf8');
  await rename(tmp, paths.queueMd);
  return full;
}
